import{a as e}from"./chunk-LXM23EYX.js";import"./chunk-IFGU66OU.js";var i=[{id:"phase-1",title:"Phase 1 \xB7 Weeks 1\u20134 \xB7 Core depth",items:[{id:"p1-read-java-interview",label:"Complete Java interview page: JVM, GC, memory model, equals/hashCode",href:"/designs/java-interview",estimateHours:8},{id:"p1-concurrency-juc",label:"Drill Java concurrency: threads, locks, ConcurrentHashMap, CompletableFuture, virtual threads overview",href:"/designs/java-interview#senior-lead-concurrency",estimateHours:10},{id:"p1-spring-boot-core",label:"Finish Spring Boot interview page: IoC, AOP, transactions, actuators",href:"/designs/spring-boot-interview",estimateHours:8},{id:"p1-spring-production",label:"Study Spring Boot production interview: configs, profiles, failure modes",href:"/designs/spring-boot-production-interview",estimateHours:6},{id:"p1-hibernate-n1",label:"Write 1-page notes on Hibernate N+1, Session/ThreadLocal, flush modes (tie to your tenant isolation story)",estimateHours:4},{id:"p1-sql-interview",label:"Complete SQL interview drills: indexes, EXPLAIN, isolation levels, deadlocks",href:"/designs/sql-interview",estimateHours:8},{id:"p1-oracle-postgres-map",label:"Map Oracle strengths (CTEs, pagination, upgrade lessons) to Postgres talking points",estimateHours:3},{id:"p1-dsa-arrays-hash",label:"DSA week cadence: 5 easy + 5 medium (arrays/hashmaps) in Java",estimateHours:8},{id:"p1-dsa-trees-graphs",label:"DSA: trees, BFS/DFS, heaps \u2014 10 mediums timed (45 min each)",estimateHours:10},{id:"p1-dsa-dp-sliding",label:"DSA: sliding window, two pointers, basic DP patterns \u2014 8 problems",estimateHours:8},{id:"p1-mock-coding-1",label:"Mock coding #1 (60 min): 1 medium array/hash + talk through complexity",estimateHours:2},{id:"p1-story-tenant-isolation",label:"Draft STAR story: multi-tenant Hibernate/ThreadLocal isolation failure + JDBC fix",estimateHours:2},{id:"p1-story-oracle-upgrade",label:"Draft STAR story: Oracle 11g\u219219c upgrade readiness for ~750 orgs",estimateHours:2},{id:"p1-equals-hashcode",label:"Drill equals/hashCode + HashMap pitfalls with 3 broken examples fixed",estimateHours:2},{id:"p1-rest-api-design",label:"Write REST API guidelines notes: versioning, idempotency headers, error model",estimateHours:2},{id:"p1-done-criteria",label:"Phase 1 done criteria: explain GC + Spring transactions + index choice without notes",estimateHours:1}]},{id:"phase-2",title:"Phase 2 \xB7 Weeks 5\u20138 \xB7 Distributed systems depth",items:[{id:"p2-kafka-interview",label:"Complete Kafka interview page end-to-end",href:"/designs/kafka-interview",estimateHours:10},{id:"p2-kafka-lab",label:"Hands-on: produce/consume with Spring Kafka; demo idempotent consumer + DLQ config",estimateHours:8},{id:"p2-outbox",label:"Study transactional outbox pattern and implement a minimal sketch",href:"/designs/transactional-outbox",estimateHours:5},{id:"p2-redis-interview",label:"Complete Spring Redis cache interview page",href:"/designs/spring-redis-cache-interview",estimateHours:6},{id:"p2-redis-locks",label:"Master Redis SET NX PX, owner-checked release, fencing tokens vs DB CAS",href:"/designs/movie-ticket-booking",estimateHours:5},{id:"p2-consistency",label:"Write comparison notes: strong vs eventual, saga vs 2PC, idempotency keys",href:"/designs/idempotent-consumer",estimateHours:4},{id:"p2-caching-pitfalls",label:"Drill cache stampede, thundering herd, TTL vs write-through, Redis vs local cache",estimateHours:3},{id:"p2-rabbitmq-bridge",label:"Map your RabbitMQ/Camunda experience to Kafka interview vocabulary (offsets, consumer groups)",estimateHours:2},{id:"p2-acid",label:"Review ACID/isolation page; be able to draw dirty/non-repeatable/phantom examples",href:"/designs/acid-transactions",estimateHours:3},{id:"p2-dsa-continue",label:"Continue DSA: 8 timed mediums (graphs + intervals + heaps)",estimateHours:8},{id:"p2-mock-design-messaging",label:"Mock system design (45 min): notification service or order pipeline with Kafka",estimateHours:2},{id:"p2-story-race-upload",label:"Draft STAR: race condition in concurrent XML media uploads + fix",estimateHours:1},{id:"p2-partition-keys",label:"Design partition key strategy for orders vs user notifications (ordering vs fan-out)",estimateHours:2},{id:"p2-rate-limit-redis",label:"Implement/sketch Redis token-bucket or sliding-window rate limiter",estimateHours:3},{id:"p2-done-criteria",label:"Phase 2 done criteria: whiteboard Kafka consumer lag + Redis lock zombie problem from memory",estimateHours:1}]},{id:"phase-3",title:"Phase 3 \xB7 Weeks 9\u201312 \xB7 Cloud, K8s, CI/CD",items:[{id:"p3-k8s-interview",label:"Complete Kubernetes interview page",href:"/designs/kubernetes-interview",estimateHours:8},{id:"p3-k8s-lab",label:"Hands-on: deploy a Spring Boot service with Deployment, Service, HPA, probes",estimateHours:6},{id:"p3-docker-multi",label:"Write multi-stage Dockerfile + healthcheck notes for Java 17 images",estimateHours:3},{id:"p3-aws-map",label:"Build AWS service map flashcards: ECS vs EKS, SQS/SNS, RDS, S3, IAM, CloudWatch, ALB",estimateHours:5},{id:"p3-gcp-transfer",label:"Translate GCP PCA knowledge to AWS interview answers (and vice versa)",estimateHours:3},{id:"p3-terraform-starter",label:"Terraform lab: VPC-ish minimal stack or ECS/RDS modules; explain state + plan/apply",estimateHours:8},{id:"p3-cicd",label:"Document CI/CD interview answers using Jenkins + Azure Pipelines experience; add GitHub Actions sketch",estimateHours:4},{id:"p3-observability",label:"Study metrics/logs/traces: Prometheus, Grafana, Splunk stories; define 3 SLOs for a checkout API",estimateHours:5},{id:"p3-elk-nginx",label:"Notes: ELK stack roles + Nginx/ALB load balancing for Principal Backend JDs",estimateHours:2},{id:"p3-dsa-hard-lite",label:"DSA: 6 harder mediums / light hards under 50 minutes each",estimateHours:8},{id:"p3-mock-design-scale",label:"Mock design: multi-AZ ticket booking or URL shortener with capacity + failure modes",estimateHours:2},{id:"p3-iam-least-privilege",label:"Sketch IAM least-privilege for a service role: S3 read, SQS consume, RDS connect",estimateHours:2},{id:"p3-capacity-backofenvelope",label:"Practice 3 back-of-envelope capacity estimates (QPS, storage, bandwidth)",estimateHours:3},{id:"p3-done-criteria",label:"Phase 3 done criteria: explain blue/green vs canary + K8s probe failure scenarios",estimateHours:1}]},{id:"phase-4",title:"Phase 4 \xB7 Weeks 13\u201316 \xB7 Staff system design + leadership",items:[{id:"p4-reshaded",label:"Internalize RESHADED interview framework",href:"/designs/interview-framework",estimateHours:3},{id:"p4-design-20",label:"Complete 20 system designs (outline + 1 diagram each): chat, feed, search, payments, inventory\u2026",estimateHours:20},{id:"p4-design-20-more",label:"Complete 20 more designs focusing on multi-region, rate limits, consistency trade-offs",estimateHours:20},{id:"p4-movie-ticket",label:"Rehearse last-ticket concurrency design aloud (DB CAS + fencing)",href:"/designs/movie-ticket-booking",estimateHours:2},{id:"p4-payment-gateway",label:"Study payment gateway + idempotency pages; practice authorize/capture saga",href:"/designs/payment-gateway",estimateHours:4},{id:"p4-leader-election",label:"Review leader election / fencing tokens for distributed coordination rounds",href:"/designs/leader-election",estimateHours:3},{id:"p4-adr-template",label:"Write 2 sample ADRs (monolith extraction boundary + messaging choice Kafka vs RabbitMQ)",estimateHours:4},{id:"p4-story-bank",label:"Finalize 8 STAR stories: upgrade, isolation bug, SQL alias, Java 17, caching, race, mentoring, incident",estimateHours:6},{id:"p4-staff-behaviors",label:"Practice Staff behaviors: influence without authority, technical strategy, saying no with trade-offs",estimateHours:3},{id:"p4-design-doc",label:"Produce one full design doc (problem, constraints, options, decision, rollout, risks)",estimateHours:5},{id:"p4-mock-staff",label:"Mock Staff round: architecture deep dive on Blackbaud modernization (45\u201360 min)",estimateHours:2},{id:"p4-rate-limiter-design",label:"Full design rehearsal: distributed rate limiter (token bucket + Redis + edge)",estimateHours:2},{id:"p4-chat-design",label:"Full design rehearsal: chat/messaging (presence, fan-out, offline store)",estimateHours:2},{id:"p4-feed-design",label:"Full design rehearsal: news feed (push vs pull, ranking, fan-out-on-write)",estimateHours:2},{id:"p4-search-design",label:"Outline design: search autocomplete + indexing pipeline (honest about Solr/Lucene depth)",estimateHours:2},{id:"p4-done-criteria",label:"Phase 4 done criteria: run a 45-min design with no prep on a random prompt",estimateHours:1}]},{id:"phase-5",title:"Phase 5 \xB7 Weeks 17\u201320 \xB7 AI fluency + fullstack bridge",items:[{id:"p5-ai-interview",label:"Complete AI engineering interview page",href:"/designs/ai-engineering-interview",estimateHours:6},{id:"p5-agentic-workflow",label:"Document your Cursor/agentic workflow: where AI helps, where you never trust it, review checklist",estimateHours:3},{id:"p5-rag-mini",label:"Build a tiny RAG demo (embeddings + retrieve + answer) over your own notes; record 5-min walkthrough",estimateHours:10},{id:"p5-react-literacy",label:"React literacy sprint: components, hooks, state, data fetching \u2014 enough to review PRs",estimateHours:8},{id:"p5-angular-story",label:"Prep Angular SPA standards + PostRobot embedding story for fullstack interviews",estimateHours:2},{id:"p5-graphql-basics",label:"GraphQL basics: schema, resolvers, N+1, when REST is better (Juniper Square pack)",estimateHours:3},{id:"p5-flink-awareness",label:"Flink/Spark awareness notes (not expertise): stream vs batch, windowing vocabulary for Twilio/Atlassian",estimateHours:4},{id:"p5-security-web",label:"Web security flashcards: XSS, CSRF, CORS, CSP, OAuth/OIDC basics",estimateHours:3},{id:"p5-mock-ai-hm",label:"Mock HM screen for AI-native role: productivity demos + engineering judgment",estimateHours:1},{id:"p5-prompt-injection",label:"Notes: prompt injection, data exfiltration via tools, and app-level guardrails",estimateHours:2},{id:"p5-eval-basics",label:"Define 5 eval cases for your RAG demo (faithfulness, refusal, citation)",estimateHours:2},{id:"p5-done-criteria",label:"Phase 5 done criteria: 5-min RAG demo + React vs Angular comparison without notes",estimateHours:1}]},{id:"phase-6",title:"Phase 6 \xB7 Weeks 21\u201324 \xB7 Interview machine",items:[{id:"p6-resume-pass",label:"Resume pass: map every bullet to Staff keywords (SLO, multi-tenant, modernization, ownership)",estimateHours:4},{id:"p6-linkedin-headline",label:"Update LinkedIn headline/about for Staff Java + distributed systems + modernization",estimateHours:1},{id:"p6-apps-cadence",label:"Start weekly cadence: 8\u201312 tailored applications (70/20/10 mix)",estimateHours:4},{id:"p6-mock-coding-3",label:"Complete 3 timed coding mocks with post-mortem notes",estimateHours:6},{id:"p6-mock-design-3",label:"Complete 3 timed system design mocks with feedback",estimateHours:6},{id:"p6-mock-behavioral-2",label:"Complete 2 Staff behavioral mocks using story bank",estimateHours:3},{id:"p6-pack-twilio",label:"Company pack: Twilio Staff/Principal (streaming, multi-region, Java/Go, SLOs)",estimateHours:3},{id:"p6-pack-netomi",label:"Company pack: Netomi Architect (Java, MySQL, Redis, AWS, ECS, low latency)",estimateHours:2},{id:"p6-pack-supply-kaseya",label:"Company pack: SupplyHouse / Kaseya Java Lead (Spring, K8s, Jenkins, ELK, mentoring)",estimateHours:2},{id:"p6-pack-juniper",label:"Company pack: Juniper Square Tech Lead (FastAPI awareness, React, GraphQL, AWS)",estimateHours:2},{id:"p6-pack-kafka-lead",label:"Company pack: Samay/Atlassian-style Kafka + streaming leads",estimateHours:2},{id:"p6-pack-generic-staff",label:"Company pack: Jobgether/Oportun generic Staff (leadership, APIs, SQL, mentoring)",estimateHours:2},{id:"p6-pack-ai-stretch",label:"Company pack: EPAM/Spydra AI-native stretch (RAG, agents, SDLC automation)",estimateHours:2},{id:"p6-offer-prep",label:"Offer prep notes: level mapping, compensation research, questions for hiring managers",estimateHours:2},{id:"p6-negotiated-questions",label:"Write 10 questions to ask interviewers (scope, on-call, Staff expectations, AI policy)",estimateHours:1},{id:"p6-comp-research",label:"Compensation research notes for Staff India remote / hybrid bands you care about",estimateHours:2},{id:"p6-done-criteria",label:"Phase 6 done criteria: can run full loop (coding + design + behavioral) in one day with recovery notes",estimateHours:1}]},{id:"ongoing",title:"Ongoing weekly habits (entire 24 weeks)",items:[{id:"hab-dsa-5",label:"Hit 5 coding problems most weeks (track in a simple spreadsheet)",estimateHours:0},{id:"hab-design-1",label:"One system design outline per week even during non-design phases",estimateHours:0},{id:"hab-story-refine",label:"Refine one STAR story weekly with metrics and decision trade-offs",estimateHours:0},{id:"hab-read-postmortem",label:"Read one public incident postmortem / engineering blog weekly",estimateHours:0},{id:"hab-ai-daily",label:"Use AI tooling daily on real work; capture one \u201Ctrust boundary\u201D lesson weekly",estimateHours:0},{id:"hab-leetcode-review",label:"Weekly spaced repetition: re-solve 3 previously solved problems blind",estimateHours:0},{id:"hab-explain-aloud",label:"Weekly: explain one production story aloud on a timer (3 minutes)",estimateHours:0},{id:"hab-network",label:"Biweekly: reach out to 2 peers/recruiters in target companies (warm or cold)",estimateHours:0}]},{id:"bonus-depth",title:"Bonus depth (optional polish for target companies)",items:[{id:"bonus-oauth-oidc",label:"OAuth2/OIDC flows: auth code, PKCE, token lifecycle \u2014 whiteboard once",estimateHours:3},{id:"bonus-mtls-gateway",label:"API gateway patterns: authn/z, rate limit, mTLS awareness notes",estimateHours:2},{id:"bonus-postgres-partition",label:"Postgres partitioning + connection pooling talking points (PgBouncer)",estimateHours:2},{id:"bonus-chaos",label:"Read and summarize one chaos/resilience testing approach for your services",estimateHours:2},{id:"bonus-cost",label:"Add cost dimension to 3 system designs (storage, egress, compute)",estimateHours:2},{id:"bonus-hotel-inventory",label:"Cross-read hotel reservation concurrency page for inventory parallels",href:"/designs/hotel-reservation",estimateHours:2},{id:"bonus-netflix-design",label:"Skim Netflix system design page for CDN/streaming vocabulary",href:"/designs/netflix",estimateHours:2},{id:"bonus-writing",label:"Publish 1 short tech write-up (ADR, blog, or LinkedIn) on a production lesson",estimateHours:4}]}];var a={meta:e,sections:[{id:"overview",title:"Overview",blocks:[{type:"markdown",value:"This is a **24-week, no-ambiguity interview roadmap** for clearing Staff / Senior Staff / Lead Backend / hands-on Architect interviews in the Java + distributed systems market. It is calibrated to a resume profile of **8+ years**, Staff title, **Spring Boot + Angular + Oracle/multi-tenant SaaS**, production debugging ownership, monolith modernization, GCP PCA + Generative AI Leader certifications \u2014 and to a LinkedIn openings dump spanning Twilio, Netomi, SupplyHouse, Kaseya, Juniper Square, EPAM, Atlassian, Sophos, and similar roles."},{type:"metrics",items:[{label:"Timeline",value:"24 weeks",hint:"~3\u20136 months wall clock"},{label:"Primary target",value:"Staff / Lead",hint:"Java backend + platforms"},{label:"Checklist items",value:"110+",hint:"Saved in localStorage"},{label:"Application mix",value:"70 / 20 / 10",hint:"Fit / bridge / stretch"}]},{type:"callout",variant:"info",title:"How to use this page",body:`1. Read **Eligibility** and **Skill gaps** once.
2. Follow the **24-week plan** week by week \u2014 each week has goal, topics, drills, deliverable, and done criteria.
3. Mark items in the **Progress checklist** as you finish them (persists in this browser).
4. Use **Interview loops**, **Story bank**, and **Company packs** the week you interview.
5. Cross-link into existing deep pages (Java, Spring, Kafka, Redis, K8s, SQL, AI) instead of re-learning from scratch.`},{type:"callout",variant:"warning",title:"Experience framing for Principal JDs",body:"Many Principal listings ask **10\u201312+ years**. With ~8+ years IC Staff experience, prioritize **Staff / Senior Staff / Lead / Architect (hands-on)** as primary applications. For selective Principal applications, lead with **scope** (750 orgs, Oracle upgrade, production escalation ownership, mentoring, standards) rather than title years alone."}]},{id:"eligibility",title:"Eligibility & Role Fit",blocks:[{type:"markdown",value:`### Your stack vs market demand

From the LinkedIn openings file, almost every serious backend/Staff role repeats the same core: **Java (or Go/Python), microservices, SQL, cloud, containers, CI/CD, distributed systems judgment, mentoring**. Your resume already covers most of that. Gaps are concentrated in **Kafka depth, Redis interview depth, Staff-bar system design reps, Terraform/AWS fluency, and AI-tooling demos**.`},{type:"table",caption:"Role-fit matrix from the collected openings.",headers:["Cluster","Examples","Fit","Action"],rows:[["Java Staff / Lead / Architect","Netomi, SupplyHouse, Kaseya, Jobgether, Oportun, Sophos (fullstack)","Fit now","Apply immediately; polish Redis/MySQL/AWS stories"],["Streaming / Kafka-heavy Staff","Twilio L4, Samay Lead Backend, Atlassian Search/Data","Fit after bridge","Weeks 5\u20138 + streaming awareness in weeks 17\u201320"],["Cloud-native platform Lead","Hired Micro Platforms, Randstad Staff/Principal","Fit after bridge","Weeks 9\u201312 K8s + Terraform + AWS map"],["Fullstack Tech Lead","Juniper Square, Sophos","Fit after bridge","Keep Angular primary; add React literacy + GraphQL basics"],["AI-native engineer","EPAM Applied Senior, Spydra Full-Stack AI","Stretch","Months 4\u20136: RAG mini + agentic workflow portfolio"],["OpenShift / Camel / middleware","Nagarro Principal Containerization","Skip","Poor ROI in 3\u20136 months"],["Compiler / runtime research","MTS Coding Research","Skip","Wrong specialty"],["Pure Python/Azure Principal","Insight Global Principal","Skip / low priority","Only if willing to rebrand stack; not this roadmap\u2019s primary path"],["FinTech domain-only","Hired FinTech SE","Secondary","Apply only where Java + distributed systems matter more than payments domain"]]},{type:"featureComparison",caption:"Target titles \u2014 what to pursue in the next 6 months.",columns:["Staff SE","Lead Backend","Architect (hands-on)","Principal (selective)"],rows:[{feature:"Primary application?",values:[!0,!0,!0,"Selective"]},{feature:"Needs Kafka depth?",values:["Often","Often","Depends","Usually"]},{feature:"Needs staff leadership stories?",values:[!0,!0,!0,!0]},{feature:"Coding rounds?",values:["Yes","Yes","Sometimes","Sometimes"]},{feature:"System design bar",values:["High","High","Very high","Very high"]}]},{type:"prosCons",title:"Non-goals for this 6-month window",pros:["Become interview-ready for Java Staff/Lead roles at scale.","Close Kafka/Redis/cloud gaps that block otherwise-fit JDs.","Build a reusable story bank and design muscle."],cons:["Do not chase OpenShift Service Mesh / Apache Camel specialist tracks.","Do not claim Flink/Solr expertise \u2014 awareness only.","Do not pivot primary language to Python/Go unless a dream role requires it."]}]},{id:"skill-gaps",title:"Skill Gap Map",blocks:[{type:"markdown",value:`### Already strong (marketable today)

- **Java + Spring Boot + Hibernate/JPA** with production scars (tenant isolation, Java 17 modules, query engines).
- **SQL depth on Oracle**, transferable to MySQL/Postgres interview talk.
- **Multi-tenant SaaS**, monolith decomposition, Angular fullstack delivery.
- **Docker/K8s/Jenkins/Azure Pipelines**, AWS/GCP exposure, Splunk production debugging.
- **Technical leadership**: mentoring, interviews, standards, 100+ production reviews.
- **Certifications**: GCP Professional Cloud Architect, Generative AI Leader.`},{type:"table",caption:"Must-close gaps (appear across most openings).",headers:["Gap","Why JDs care","How this roadmap closes it","Done when"],rows:[["Kafka + event-driven design","Twilio, Samay, Atlassian, Randstad, most Staff platforms","Weeks 5\u20138 + outbox/idempotency labs","Explain consumer groups, lag, exactly-once illusions, DLQ, outbox"],["Redis production patterns","Netomi, SupplyHouse, caching/rate-limit interviews","Redis page + lock/fencing drills via ticket booking","Whiteboard cache + distributed lock failure modes"],["Staff-bar system design","Every Staff+ loop","Weeks 13\u201316: 40 designs + RESHADED","45-min random design without prep"],["Timed DSA / coding","Most companies still screen with it","Weekly Java DSA cadence phases 1\u20136","Consistent medium solve in ~35\u201340 min with tests"],["Observability + incident leadership","Principal/Staff ownership language","SLO drills + story bank + Splunk narratives","Define SLOs and lead a mock postmortem"],["Terraform + AWS depth","ECS/EKS/SQS/SNS on many JDs","Weeks 9\u201312 cloud map + Terraform lab","Compare ECS vs EKS; sketch IaC for a service"],["AI-assisted engineering fluency","Nearly every 2025\u201326 JD","Weeks 17\u201320 workflow docs + RAG mini","5-min demo of agentic workflow + trust boundaries"]]},{type:"heading",level:3,text:"Quick wins (2\u20134 weeks each)"},{type:"bestPractices",title:"Highest leverage early investments",practices:["**Redis + Spring Cache** \u2014 short study, huge JD coverage.","**Kafka fundamentals \u2192 production patterns** \u2014 unlocks streaming Staff roles.","**Staff STAR bank** \u2014 turns Blackbaud work into interview gold.","**React literacy (read/review level)** \u2014 unlocks fullstack Lead screens without abandoning Angular."]},{type:"heading",level:3,text:"Secondary (months 4\u20136 only)"},{type:"markdown",value:`- Light **RAG + agents** project for EPAM/Spydra-style roles.
- **Flink/Spark vocabulary** for Twilio/Atlassian \u2014 conceptual, not expertise claim.
- **GraphQL basics** for Juniper Square.
- Optional Go/Python syntax familiarity only if a specific pipeline requires it.`}]},{id:"roadmap-24-weeks",title:"24-Week Roadmap",blocks:[{type:"mermaid",caption:"Six phases from core depth to interview machine.",definition:`flowchart LR
  P1[Weeks1to4_CoreDepth] --> P2[Weeks5to8_Distributed]
  P2 --> P3[Weeks9to12_CloudOps]
  P3 --> P4[Weeks13to16_StaffBar]
  P4 --> P5[Weeks17to20_AIPlusFullstack]
  P5 --> P6[Weeks21to24_InterviewMachine]`},{type:"timeline",items:[{title:"Phase 1 \xB7 Weeks 1\u20134",meta:"Core depth",description:"Java concurrency, Spring Boot production, SQL/Oracle\u2192Postgres talk tracks, DSA warm-up, first STAR drafts."},{title:"Phase 2 \xB7 Weeks 5\u20138",meta:"Distributed",description:"Kafka, Redis, outbox, locking/fencing, consistency, messaging mock design."},{title:"Phase 3 \xB7 Weeks 9\u201312",meta:"Cloud & ops",description:"K8s depth, Docker, CI/CD narrative, Terraform starter, AWS service map, SLOs."},{title:"Phase 4 \xB7 Weeks 13\u201316",meta:"Staff bar",description:"40 system designs, ADRs, leadership behaviors, full design doc, Staff mock."},{title:"Phase 5 \xB7 Weeks 17\u201320",meta:"AI + fullstack bridge",description:"AI tooling portfolio, RAG mini, React literacy, GraphQL/Flink awareness."},{title:"Phase 6 \xB7 Weeks 21\u201324",meta:"Interview machine",description:"Mocks, company packs, application cadence, offer prep."}]},{type:"callout",variant:"tip",title:"Weekly time budget (suggested)",body:"**10\u201314 focused hours/week** if employed full-time: 4h DSA, 4h deep tech, 2h design/story, 2h lab/mocks. Increase to **20h** in phase 6. If you miss a week, slip the calendar \u2014 do not skip Phase 2 Kafka/Redis."}]},{id:"phase-1",title:"Phase 1 \u2014 Weeks 1\u20134 \xB7 Core Depth",blocks:[{type:"markdown",value:"**Phase goal:** Become fluent again at the Senior\u2192Staff technical screen: Java concurrency, Spring Boot production behavior, SQL performance, and clean coding under time pressure."},{type:"expandable",title:"Week 1 \u2014 Java concurrency & JVM",open:!0,blocks:[{type:"markdown",value:"- **Goal:** Explain memory model, GC choice trade-offs, and common concurrency bugs.\n- **Study:** [/designs/java-interview](/designs/java-interview) \u2014 JVM, GC, threads, locks, JUC.\n- **Drills:** Implement a thread-safe cache; diagnose a deadlock snippet; compare `synchronized` vs `ReentrantLock` vs `ConcurrentHashMap`.\n- **Deliverable:** 1-page cheat sheet: happens-before, visibility, false sharing (awareness).\n- **Done when:** You can teach ThreadLocal hazards using your tenant-isolation incident."}]},{type:"expandable",title:"Week 2 \u2014 Spring Boot production",blocks:[{type:"markdown",value:`- **Goal:** Interview-ready Spring: transactions, proxies, configs, actuators, failure modes.
- **Study:** [/designs/spring-boot-interview](/designs/spring-boot-interview), [/designs/spring-boot-production-interview](/designs/spring-boot-production-interview).
- **Drills:** Draw \`@Transactional\` proxy pitfalls; explain dirty checking; list 5 production metrics you would alert on.
- **Deliverable:** Notes linking Hibernate Session + ThreadLocal to your JDBC fix story.
- **Done when:** You can walk a broken transaction boundary and propose a fix in <10 minutes.`}]},{type:"expandable",title:"Week 3 \u2014 SQL depth (Oracle \u2192 portable talk)",blocks:[{type:"markdown",value:`- **Goal:** Sound equally strong on MySQL/Postgres JDs while owning Oracle expertise.
- **Study:** [/designs/sql-interview](/designs/sql-interview); revisit CTEs, indexes, isolation.
- **Drills:** EXPLAIN a slow join; design indexes for a multi-tenant \`org_id\` filter; narrate Oracle 19c upgrade risks.
- **Deliverable:** \u201COracle lessons \u2192 Postgres/MySQL\u201D translation sheet.
- **Done when:** You pick an isolation level for booking/payments with clear anomalies listed.`}]},{type:"expandable",title:"Week 4 \u2014 DSA warm-up + first stories",blocks:[{type:"markdown",value:`- **Goal:** Rebuild timed problem-solving muscle; draft two flagship STAR stories.
- **Study:** Arrays, hash maps, two pointers, trees BFS/DFS \u2014 Java solutions only.
- **Drills:** 5 easy + 10 medium timed; mock coding #1.
- **Deliverable:** STAR drafts for tenant isolation + Oracle upgrade.
- **Done when:** Medium array/hash problem solved with tests in ~40 minutes.`}]},{type:"callout",variant:"summary",title:"Phase 1 exit criteria",body:"GC + Spring transactions + index selection explainable without notes; 2 STAR stories drafted; coding mock #1 completed."}]},{id:"phase-2",title:"Phase 2 \u2014 Weeks 5\u20138 \xB7 Distributed Systems",blocks:[{type:"markdown",value:"**Phase goal:** Close the highest-frequency market gaps \u2014 **Kafka** and **Redis** \u2014 and connect them to correctness patterns you already understand from production concurrency work."},{type:"expandable",title:"Week 5 \u2014 Kafka fundamentals \u2192 production",open:!0,blocks:[{type:"markdown",value:`- **Goal:** Speak Kafka like someone who has operated consumer lag, not only read docs.
- **Study:** [/designs/kafka-interview](/designs/kafka-interview).
- **Drills:** Partitions vs consumer groups; ordering keys; retry/DLQ; \u201Cexactly-once\u201D marketing vs reality.
- **Lab:** Spring Kafka producer/consumer with idempotent consumer keys.
- **Done when:** You map RabbitMQ experience to Kafka vocabulary without confusion.`}]},{type:"expandable",title:"Week 6 \u2014 Outbox, idempotency, sagas",blocks:[{type:"markdown",value:`- **Goal:** Dual-write safety and async workflows.
- **Study:** [/designs/transactional-outbox](/designs/transactional-outbox), [/designs/idempotent-consumer](/designs/idempotent-consumer).
- **Drills:** Design order\u2192payment\u2192inventory saga; list compensation actions.
- **Deliverable:** Sequence diagram for outbox relay.
- **Done when:** You reject \u201Cjust publish after commit in the app thread\u201D with a better design.`}]},{type:"expandable",title:"Week 7 \u2014 Redis caching & locks",blocks:[{type:"markdown",value:`- **Goal:** Production Redis answers for Netomi/SupplyHouse-style rounds.
- **Study:** [/designs/spring-redis-cache-interview](/designs/spring-redis-cache-interview), [/designs/movie-ticket-booking](/designs/movie-ticket-booking) (locks + fencing).
- **Drills:** Cache stampede; SET NX PX; Lua owner delete; fencing tokens vs DB conditional update.
- **Done when:** You explain why a lease expiry does not stop a zombie writer.`}]},{type:"expandable",title:"Week 8 \u2014 Consistency synthesis + mock",blocks:[{type:"markdown",value:`- **Goal:** Integrate messaging + cache + DB into one design narrative.
- **Study:** [/designs/acid-transactions](/designs/acid-transactions).
- **Drills:** Mock design: notification service or ecommerce order pipeline.
- **Deliverable:** STAR for concurrent upload race.
- **Done when:** Whiteboard Kafka lag + Redis zombie problem from memory.`}]}]},{id:"phase-3",title:"Phase 3 \u2014 Weeks 9\u201312 \xB7 Cloud, K8s, CI/CD",blocks:[{type:"markdown",value:"**Phase goal:** Turn \u201CI have used Docker/K8s/AWS/GCP\u201D into **interview-precise** platform answers: probes, rollouts, IAM, ECS vs EKS, Terraform state, SLOs."},{type:"expandable",title:"Week 9 \u2014 Kubernetes depth",open:!0,blocks:[{type:"markdown",value:`- **Study:** [/designs/kubernetes-interview](/designs/kubernetes-interview).
- **Lab:** Deploy Spring Boot with readiness/liveness, resource requests, HPA.
- **Done when:** You diagnose CrashLoopBackOff and a failing readiness probe scenario.`}]},{type:"expandable",title:"Week 10 \u2014 AWS (+ GCP transfer)",blocks:[{type:"markdown",value:`- **Build flashcards:** ECS, EKS, Lambda, SQS, SNS, RDS, S3, IAM, ALB, CloudWatch.
- **Transfer:** Map GCP PCA knowledge (GKE, Pub/Sub, Cloud SQL) to AWS equivalents.
- **Done when:** You can justify ECS vs EKS for a mid-size Spring estate.`}]},{type:"expandable",title:"Week 11 \u2014 Terraform + CI/CD",blocks:[{type:"markdown",value:`- **Lab:** Minimal Terraform for a container service + datastore (even locally mocked).
- **Narrative:** Jenkins + Azure Pipelines experience \u2192 modern GitHub Actions sketch.
- **Done when:** Explain state, plan/apply, secrets handling, and pipeline quality gates.`}]},{type:"expandable",title:"Week 12 \u2014 Observability & SLOs",blocks:[{type:"markdown",value:`- Define **3 SLOs** for a checkout/donation API (availability, latency, error budget).
- Connect Splunk incident stories to metrics/logs/traces.
- Notes on ELK + load balancers for SupplyHouse-style JDs.
- **Done when:** Blue/green vs canary + alert-on-symptoms explained cleanly.`}]}]},{id:"phase-4",title:"Phase 4 \u2014 Weeks 13\u201316 \xB7 Staff System Design & Leadership",blocks:[{type:"markdown",value:"**Phase goal:** Hit the Staff bar: structured design under time, multi-region thinking, written architectural judgment, and leadership stories that prove influence."},{type:"expandable",title:"Week 13 \u2014 Framework + first 10 designs",open:!0,blocks:[{type:"markdown",value:`- Internalize [/designs/interview-framework](/designs/interview-framework) (RESHADED).
- Outline 10 designs (chat, news feed, URL shortener, rate limiter, ticket booking, etc.).
- Rehearse [/designs/movie-ticket-booking](/designs/movie-ticket-booking) concurrency aloud.`}]},{type:"expandable",title:"Week 14 \u2014 Designs 11\u201325 + payments/consistency",blocks:[{type:"markdown",value:`- Continue outlines with capacity estimates and failure modes.
- Deep dive [/designs/payment-gateway](/designs/payment-gateway), idempotency, outbox.
- Practice authorize \u2192 capture \u2192 reconcile.`}]},{type:"expandable",title:"Week 15 \u2014 Designs 26\u201340 + coordination",blocks:[{type:"markdown",value:`- Multi-region, search, streaming pipelines (conceptual).
- [/designs/leader-election](/designs/leader-election) for fencing/coordination rounds.
- Write ADR #1: service extraction boundary from a monolith.`}]},{type:"expandable",title:"Week 16 \u2014 Leadership + design doc + Staff mock",blocks:[{type:"markdown",value:`- Finalize **8 STAR stories** (see Story bank).
- Write one full design doc + ADR #2 (Kafka vs RabbitMQ).
- Mock Staff architecture deep dive on Luminate modernization.
- **Exit:** Random 45-min design with no prep.`}]}]},{id:"phase-5",title:"Phase 5 \u2014 Weeks 17\u201320 \xB7 AI Fluency + Fullstack Bridge",blocks:[{type:"markdown",value:"**Phase goal:** Cover the \u201CAI-native development\u201D checkbox on modern JDs and unlock fullstack Lead screens without pretending to be a React specialist."},{type:"expandable",title:"Week 17 \u2014 AI tooling as an engineering practice",open:!0,blocks:[{type:"markdown",value:`- Study [/designs/ai-engineering-interview](/designs/ai-engineering-interview).
- Document Cursor/agentic workflows: prompts, tests-first, when to distrust output.
- Prepare a 5-minute live demo narrative (refactor + review checklist).`}]},{type:"expandable",title:"Week 18 \u2014 Mini RAG project",blocks:[{type:"markdown",value:`- Build a small RAG over your interview notes or public docs (embeddings + retrieval + answer).
- Record a short walkthrough: architecture, failure modes, evaluation.
- This is **stretch ammo** for EPAM/Spydra \u2014 not your primary application story.`}]},{type:"expandable",title:"Week 19 \u2014 React literacy + Angular stories",blocks:[{type:"markdown",value:`- Learn enough React (components, hooks, fetching) to review PRs and discuss trade-offs.
- Prep Angular SPA standards + PostRobot embedding story.
- GraphQL basics for Juniper Square.`}]},{type:"expandable",title:"Week 20 \u2014 Streaming awareness + web security",blocks:[{type:"markdown",value:`- Flink/Spark **vocabulary only** for Twilio/Atlassian screens.
- XSS/CSRF/CORS/CSP/OAuth flashcards for Sophos-style fullstack.
- **Exit:** RAG demo + Angular vs React comparison cold.`}]}]},{id:"phase-6",title:"Phase 6 \u2014 Weeks 21\u201324 \xB7 Interview Machine",blocks:[{type:"markdown",value:"**Phase goal:** Convert preparation into offers: polished artifacts, weekly application volume, and repeated full-loop mocks."},{type:"table",headers:["Week","Focus","Quota"],rows:[["21","Resume + LinkedIn + story polish; start applications","8 tailored apps"],["22","Coding mocks + Kafka/Redis company packs","2 coding mocks, 10 apps"],["23","System design mocks + Staff behavioral","2 design + 1 behavioral, 10 apps"],["24","Targeted packs + offer prep + recovery notes","Full-loop day simulation"]]},{type:"bestPractices",title:"Application mix (do not improvise)",practices:["**70%** strong-fit Java Staff/Lead/Architect (Netomi, Kaseya, SupplyHouse, Sophos, Jobgether, Oportun, Spreetail, Randstad).","**20%** bridge roles needing Kafka/Redis/AWS depth (Twilio Staff, Samay, platform roles).","**10%** stretch AI/fullstack (EPAM, Spydra, Juniper Square).","**0%** OpenShift/Camel specialist and compiler-research roles \u2014 skip."]}]},{id:"checklist",title:"Progress Checklist",blocks:[{type:"markdown",value:"Check items as you complete them. Progress is stored in **this browser\u2019s localStorage** under `sd-roadmap:staff-interview-roadmap`. Use filters to focus on open work. Reset clears only this roadmap\u2019s checks."},{type:"roadmapChecklist",storageKey:"staff-interview-roadmap",title:"Staff interview roadmap \u2014 track completion",groups:i}]},{id:"interview-loops",title:"Interview Loop Playbooks",blocks:[{type:"mermaid",caption:"Typical Staff+ loop (order varies by company).",definition:`flowchart LR
  Recruiter[RecruiterScreen] --> HM[HiringManager]
  HM --> Coding[CodingRound]
  Coding --> Design[SystemDesign]
  Design --> Staff[StaffLeadership]
  Staff --> Offer[OfferAndTeamMatch]`},{type:"table",caption:"What each round evaluates at Staff vs Senior.",headers:["Round","Senior bar","Staff+ bar","Your angle"],rows:[["Recruiter","Skills match","Scope, level signal, domain","Staff ownership of modernization + production escalation"],["Hiring manager","Delivery","Strategy, influence, ambiguity","Cross-team standards, mentoring, risk calls (Oracle upgrade)"],["Coding","Correct mediums","Clarity, tests, trade-offs, speed","Java idioms; talk complexity; don\u2019t rush mutations"],["System design","Working design","Failure modes, SLOs, evolvability, cost","Multi-tenant + concurrency + ops stories"],["Leadership / deep dive","Teamwork","Org impact, technical judgment under conflict","Story bank + ADRs + incident leadership"]]},{type:"callout",variant:"tip",title:"Recruiter screen script (90 seconds)",body:"Staff Engineer on a multi-tenant Java fundraising platform serving ~750 organizations. I own hard production issues (Hibernate/tenant isolation, Oracle upgrades, query engines), lead incremental monolith decomposition to Spring Boot + Angular, and mentor engineers while setting SPA standards. I\u2019m targeting Staff/Lead roles where backend platforms, correctness under concurrency, and production ownership matter. Recently deepening Kafka/Redis/event-driven design and Staff-level system design reps."}]},{id:"story-bank",title:"Story Bank (STAR)",blocks:[{type:"markdown",value:"Prepare these as **2\u20133 minute** spoken stories with Situation \u2192 Task \u2192 Action \u2192 Result, plus one **decision trade-off** and one **what you\u2019d do differently**."},{type:"table",headers:["Story","Situation / Task","Action (highlight)","Result / metric cue","Use in"],rows:[["Tenant isolation failure","Production-only multi-tenant auth failures","Traced Hibernate Criteria + ThreadLocal + shared connections; shipped JDBC fix","Restored isolation; stopped auth failures","Debugging, Hibernate, multi-tenant design"],["Oracle 11g \u2192 19c","Platform readiness across ~750 orgs","Phased env fixes: encryption, JDBC, SQL, pagination features","Unblocked upgrade; faster long queries","Leadership, risk, databases"],["Dynamic SQL alias collision","Customer-specific fields broke reporting","Generalized alias strategy in query engine","Reliable reporting across combinations","Abstraction design, SQL"],["Java 17 module access","Deployments failing on reflection","Identified `--add-opens` requirements for runtime","Unblocked Java 17 production","JVM, platform upgrades"],["Login latency cleanup","Decade of expired sessions/tokens","Automated cleanup jobs","Faster login; less background load","Performance, pragmatism"],["Campaign caching + CTEs","Query/page-load pressure on donations","Program-level cache + SQL rewrite","Reduced load (qualitative OK if no exact %)","Caching, SQL optimization"],["Concurrent media upload race","Photo/video XML updates racing","Synchronized update paths","Reliable persistence under concurrency","Concurrency, correctness"],["Angular standards + mentoring","Inconsistent SPA practices","Standards, interviews, onboarding mentorship","100+ reviews; stronger release confidence","Staff leadership / influence"],["Telstra migration (bonus)","Copper\u2192fiber workflow orchestration","Spring services + Camunda + RabbitMQ + Splunk incidents","Migrations without subscription disruption","Messaging, workflows, ops"]]},{type:"callout",variant:"warning",title:"Staff upgrade to every story",body:"Add: who else was involved, what alternative you rejected, how you reduced blast radius, and how you prevented recurrence (test, alert, runbook, design rule). Senior stories end at the fix; Staff stories end at the **system improvement**."}]},{id:"company-packs",title:"Company / JD Cluster Packs",blocks:[{type:"expandable",title:"Twilio Staff / Principal",open:!0,blocks:[{type:"markdown",value:`**Emphasize:** high-scale messaging mental models, multi-region, SLOs, Java concurrency, Kafka/Kinesis vocabulary, containers, CI/CD, AI tooling.
**Prep:** Phase 2 Kafka + Phase 3 cloud + Phase 4 multi-region designs.
**Watch-outs:** Don\u2019t overclaim Flink; be honest about RabbitMQ\u2192Kafka transfer learning.
**Ask them:** event volume, multi-region active-active vs failover, on-call model for Staff.`}]},{type:"expandable",title:"Netomi Software Architect",blocks:[{type:"markdown",value:`**Emphasize:** Java/Spring, MySQL tuning, Redis caching/rate limits, AWS + ECS, low-latency APIs, mentoring.
**Prep:** SQL + Redis weeks; ECS vs EKS talking points; latency budgets.
**Story fit:** caching CTEs, login cleanup, production debugging.`}]},{type:"expandable",title:"SupplyHouse Principal Backend / Kaseya Lead",blocks:[{type:"markdown",value:`**Emphasize:** Spring microservices, Docker/K8s, Jenkins CI/CD, MySQL, Redis, ELK, Nginx/HA, mentoring, code quality.
**Prep:** Phase 3 observability + CI/CD narrative; leadership stories.
**Bonus:** React familiarity if fullstack expectations appear.`}]},{type:"expandable",title:"Juniper Square Tech Lead (fullstack)",blocks:[{type:"markdown",value:`**Emphasize:** architecture leadership across FE/BE, Angular depth, React literacy, AWS, Docker/K8s, async processing (Celery/RabbitMQ analogs).
**Prep:** Phase 5 React + GraphQL basics; be ready to discuss FastAPI as a learnable peer to Spring.
**Honesty:** Primary backend is Java/Spring; productive in Python APIs within weeks if required.`}]},{type:"expandable",title:"Kafka / streaming leads (Samay, Atlassian-style)",blocks:[{type:"markdown",value:`**Emphasize:** Kafka expertise, integration architecture, incident leadership, Java stream processing awareness.
**Prep:** Kafka page + outbox + consumer lag war stories (lab-derived).
**Atlassian extras:** search/Lucene awareness only if you\u2019ve studied it \u2014 otherwise stay on pipelines/K8s/Java APM.`}]},{type:"expandable",title:"Generic Staff (Jobgether, Oportun)",blocks:[{type:"markdown",value:`**Emphasize:** end-to-end ownership, frameworks that multiply team output, mentoring seniors, cross-team delivery, REST + SQL + cloud.
**Prep:** Story bank + design doc + influence examples.
**Coding:** still practice \u2014 these loops often keep DSA.`}]},{type:"expandable",title:"AI-native stretch (EPAM, Spydra)",blocks:[{type:"markdown",value:`**Emphasize:** GCP Generative AI Leader, daily agentic workflows, RAG mini, judgment about hallucinations, SDLC integration.
**Prep:** Phase 5 only after Phases 1\u20134 are solid.
**Positioning:** Staff engineer who accelerates delivery with AI \u2014 not a research ML engineer.`}]}]},{id:"application-strategy",title:"Application Strategy & Metrics",blocks:[{type:"markdown",value:`### Weekly operating metrics (Phase 6)

- Applications submitted: **8\u201312** tailored (not spray).
- Conversations / screens: track conversion; if <15% recruiter reply, rewrite LinkedIn + first resume bullets.
- Mocks: **\u22652** timed technical reps/week.
- Checklist: finish open Phase 1\u20133 items before heavy applying if still incomplete.`},{type:"heading",level:3,text:"Resume bullet templates (Staff language)"},{type:"code",language:"markdown",filename:"resume-bullet-patterns.md",code:`Owned production incident response for multi-tenant Java services (~750 orgs),
diagnosing Hibernate/ThreadLocal isolation failures and shipping a JDBC fix
that restored tenant boundaries and stopped authentication failures.

Led Oracle 11g\u219219c readiness on a business-critical fundraising platform:
resolved encryption, JDBC, SQL compatibility, and pagination issues across
phased environments; improved long-running query performance with newer SQL features.

Drove incremental monolith decomposition into Spring Boot services and Angular
modules, defining boundaries that reduced coupling without disrupting customer
fundraising workflows.

Established Angular SPA standards and mentored engineers through architecture
reviews and 100+ production-focused code reviews, improving release confidence.`},{type:"callout",variant:"info",title:"Keyword coverage to weave naturally",body:"microservices, multi-tenant, observability, SLO/error budget, incident postmortem, CI/CD, Docker/Kubernetes, Redis caching, event-driven (as you gain Kafka), idempotency, technical leadership, design reviews, AWS/GCP."}]},{id:"study-links",title:"Deep Study Links",blocks:[{type:"markdown",value:"Use this platform\u2019s existing pages as the curriculum spine. The roadmap tells you **when**; these pages tell you **what**."},{type:"table",headers:["Topic","Page"],rows:[["Interview framework","[/designs/interview-framework](/designs/interview-framework)"],["Java","[/designs/java-interview](/designs/java-interview)"],["Spring Boot","[/designs/spring-boot-interview](/designs/spring-boot-interview)"],["Spring production","[/designs/spring-boot-production-interview](/designs/spring-boot-production-interview)"],["SQL","[/designs/sql-interview](/designs/sql-interview)"],["Kafka","[/designs/kafka-interview](/designs/kafka-interview)"],["Redis / cache","[/designs/spring-redis-cache-interview](/designs/spring-redis-cache-interview)"],["Kubernetes","[/designs/kubernetes-interview](/designs/kubernetes-interview)"],["AI engineering","[/designs/ai-engineering-interview](/designs/ai-engineering-interview)"],["Ticket concurrency / fencing","[/designs/movie-ticket-booking](/designs/movie-ticket-booking)"],["Transactional outbox","[/designs/transactional-outbox](/designs/transactional-outbox)"],["Idempotent consumers","[/designs/idempotent-consumer](/designs/idempotent-consumer)"],["Payment gateway","[/designs/payment-gateway](/designs/payment-gateway)"],["Leader election","[/designs/leader-election](/designs/leader-election)"],["ACID / isolation","[/designs/acid-transactions](/designs/acid-transactions)"]]}]},{id:"interview-questions",title:"Self-Check Interview Questions",blocks:[{type:"interviewQa",title:"You are ready when you can answer these cold",items:[{question:"Explain a production bug only you could have caught \u2014 what changed in the system afterward?",answer:"Use the tenant isolation or SQL alias story. End with a prevention mechanism (test, invariant, review checklist), not only the patch."},{question:"How would you stop double-selling the last inventory item across two app servers?",answer:"Atomic DB conditional update + unique constraint as source of truth; Redis lease for coordination; fencing tokens against zombie holders; never charge on a stale read. See movie-ticket-booking."},{question:"Kafka consumer is lagging \u2014 how do you diagnose and mitigate?",answer:"Check partition count vs concurrency, processing time, GC, downstream DB, poison messages, rebalance storms; scale consumers carefully; consider parallelization keys and idempotent handlers."},{question:"When is Redis the wrong cache?",answer:"Strongly consistent reads required without invalidation design; huge working set with poor hit rate; need complex queries; or when local Caffeine + DB is simpler and good enough."},{question:"ECS or EKS for a Spring microservice estate?",answer:"ECS: less ops overhead, AWS-native. EKS: portability, richer ecosystem, more complexity. Choose based on team skills, multi-cloud needs, and existing platform investment."},{question:"How do you use AI tooling without shipping hallucinations?",answer:"Constrain tasks, require tests, review diffs like a junior PR, never trust security-sensitive code blindly, keep architecture decisions human-owned. Demo a concrete workflow."},{question:"Tell me about a time you influenced engineers without authority.",answer:"Angular SPA standards, mentoring, design reviews, interview loops \u2014 show adoption metrics or qualitative team outcomes."},{question:"Design a multi-tenant SaaS data model \u2014 which isolation strategy and why?",answer:"Compare shared schema + tenant_id, schema-per-tenant, DB-per-tenant. Relate to your shared-database schema-isolated Oracle experience and failure modes (cross-tenant leakage)."}]}]},{id:"summary",title:"Summary",blocks:[{type:"callout",variant:"summary",title:"Key takeaways",body:`1. You are **already eligible** for most Java Staff/Lead/Architect openings \u2014 apply while training gaps.
2. The non-negotiable bridges are **Kafka, Redis, Staff system design reps, DSA cadence, AWS/Terraform fluency, and AI-tooling demos**.
3. Follow the **24-week phases in order**; do not skip Phase 2.
4. Use the **checklist** (localStorage) as your source of truth for completion.
5. Skip low-ROI specialties (OpenShift/Camel/compilers); keep AI roles as **10% stretch**.
6. Convert Blackbaud scars into **Staff stories** that end in system-level prevention.`},{type:"references",items:[{label:"System Design Interview Framework (RESHADED)",url:"/designs/interview-framework",source:"This platform"},{label:"Java Interview",url:"/designs/java-interview",source:"This platform"},{label:"Kafka Interview",url:"/designs/kafka-interview",source:"This platform"},{label:"Movie Ticket Booking \u2014 concurrency & fencing",url:"/designs/movie-ticket-booking",source:"This platform"}]}]}]},o=a;export{o as default};
